"""Authoring tool: produces complete JSON lessons from reviewed source rows and authored blueprints.
Run from repository root. Does not approve institutional pedagogy or synthesize audio.
"""
import json
from pathlib import Path
BASE=Path('apps/web/src/content')
subjects={'matematicas':'Matemáticas','lengua-castellana':'Lengua Castellana','ciencias-sociales':'Ciencias Sociales'}
def row(area,grade):
 table=grade if area=='matematicas' else min(grade,4) if area=='lengua-castellana' else 1 if grade<3 else 2 if grade==3 else 3
 data=json.load(open(f'docs/fuentes/extractos/{area}-2026.json'))
 item=next(t for t in data if t.get('table')==table)
 r=next(r for r in item['rows'] if r['cells'][0].strip()=='4')
 return table,r

def activity(kind,prompt,answer,why,obj,choices=None,accepted=None):
 a=dict(kind=kind,prompt=prompt,answer=answer,explanation=why,objective=obj)
 if choices:a['choices']=choices
 if accepted:a['acceptedAnswers']=accepted
 return a

def choice(q,a,why,obj,options):return activity('choice',q,a,why,obj,options)
def number(q,a,why,obj):return activity('number',q,a,why,obj)
def text(q,a,why,obj,accepted=None):return activity('text',q,a,why,obj,accepted=accepted)
def decimal(q,a,why,obj):return activity('decimal',q,a,why,obj)
def order(q,answer,choices,why,obj):return activity('order',q,'|'.join(answer),why,obj,choices)
def concept(title,definition,example,act,hint,symbol='🌱',visual=None):return dict(title=title,definition=definition,example=example,activity=act,hint=hint,symbol=symbol,visual=visual)
def written(q,solution):return (q,solution)

def make(area,grade,slug,title,opening,concepts,exercises,mission,checks,extra=None):
 table,r=row(area,grade);cells=r['cells'];uid=f'g{grade}-{area}-p4-{slug}';steps=[]
 def add(phase,title,instruction,lines=None,hint='Escucha otra vez. Haz una acción a la vez y vuelve al ejemplo si lo necesitas.',act=None,symbol=None,visual=None,date=False):
  s=dict(id=f'{uid}-{len(steps)+1:02}',phase=phase,title=title,instruction=instruction,text=lines or [],hint=hint)
  if act:s['activity']=act
  if symbol:s['symbol']=symbol
  if visual:s['visual']=visual
  if date:s['showDate']=True
  steps.append(s)
 add('Hoy aprenderé',title,f'Busca tu cuaderno de {subjects[area]}, lápiz y colores. Escucha cada consigna, realiza una tarea y pulsa Continuar. Puedes descansar y reanudar después. Hoy recorrerás ocho momentos.', ['Necesitas cuaderno, lápiz y colores. Los dibujos digitales son una alternativa a los objetos.','Escuchar y pedir una pista no te quita puntos. Tu docente revisará el trabajo físico.'],symbol='👋')
 add('Descubro','Una situación de nuestra vereda',opening,['Observa o imagina la situación. Cuenta tu idea en voz baja; todavía no necesitas escribir.'],symbol=concepts[0]['symbol'],visual=concepts[0].get('visual'))
 for c in concepts:add('Aprendo',c['title'],'Escucha la explicación y sigue el ejemplo resuelto. Señala los datos o las palabras que se mencionan.',[c['definition'],c['example']],c['hint'],symbol=c['symbol'],visual=c.get('visual'))
 add('Mi cuaderno','Fecha y título','Abre tu cuaderno. Copia la fecha visible y luego el título. Deja una línea antes de continuar.',[title],date=True)
 for c in concepts:add('Mi cuaderno','Escribe: '+c['title'],'Copia la idea y el ejemplo que aparecen aquí. Puedes pausar el audio y escribir despacio.',[c['title'],c['definition'],c['example']],c['hint'])
 for i,(q,sol) in enumerate(exercises,1):add('Mi cuaderno',f'Resuelve el ejercicio {i}',f'Copia completo el ejercicio {i}. Debajo escribe, dibuja o resuelve exactamente lo que pide. No mires la revisión hasta terminar.',[f'{i}. {q}'])
 for i,(q,sol) in enumerate(exercises,1):add('Mi cuaderno',f'Revisa el ejercicio {i}','Compara con tu cuaderno. Si hay diferencias, revisa el ejemplo y corrige. El programa no ha visto tu escritura ni tu dibujo.',[f'{i}. {q}',sol])
 for c in concepts:add('Practico','Practica: '+c['title'],'Realiza el reto de la pantalla y pulsa Comprobar. Si aparece Todavía no, corrige tu respuesta o pide una pista.',hint=c['hint'],act=c['activity'],symbol=c['symbol'],visual=c.get('visual'))
 add('Mi misión',mission['title'],mission['instruction'],mission.get('text'),mission.get('hint','Usa las ideas y ejemplos que acabas de aprender.'),mission.get('activity'),mission.get('symbol','🏡'),mission.get('visual'))
 for i,check in enumerate(checks,1):add('Demuestro lo aprendido',f'Reto {i}: '+check['title'],'Intenta resolver por tu cuenta. Puedes escuchar la consigna y usar una pista si la necesitas; quedará registrada para el docente.',check.get('text'),check['hint'],check['activity'],check.get('symbol'),check.get('visual'))
 add('Terminé','Terminé y comparto','Elige cómo te sentiste. Muestra al docente tu cuaderno abierto en el título, las ideas, los ejemplos y los ejercicios corregidos. Presenta también el producto de la misión y explica qué hiciste.', ['Revisa que cada ejercicio tenga una respuesta. Puedes pedir al docente una devolución sobre tus dibujos y explicaciones.','Las respuestas de la pantalla se guardan en este equipo. Tu confirmación de escritura no demuestra la calidad del cuaderno.'])
 plans=[]
 for g in [grade]:
  plan=f'plan-{ "lengua" if area=="lengua-castellana" else "sociales" if area=="ciencias-sociales" else area}-{g}-p4.docx'
  if (Path('docs/fuentes')/plan).exists():plans.append(dict(file='docs/fuentes/'+plan,locator='Encabezado de cuarto período; ejes temáticos y desarrollo de los temas correspondientes'))
 if area=='lengua-castellana' and grade>=4:plans=[dict(file='docs/fuentes/plan-lengua-4-5-p4.docx',locator='Tabla 1 y párrafos Género dramático / El guion teatral')]
 u=dict(id=uid,version=1,title=title,grade=grade,subject=subjects[area],period=4,approach='primary',source=dict(file=f'docs/fuentes/{area}-2026.docx',locator=f'Tabla {table}, fila {r["row"]}, período 4; columnas de competencia, aprendizaje, evidencia y eje temático',status='FUENTE_CONSULTADA',complementary=plans),curriculum=dict(competence=cells[3].strip(),learning=[x.strip() for x in cells[6 if area=='matematicas' else 5].split('\n') if x.strip()],evidence=[x.strip() for x in cells[5 if area=='matematicas' else 6].split('\n') if x.strip() and x.strip()!='.'],dba=cells[2].strip() or None,themes=[x.strip() for x in cells[7].split('\n') if x.strip()],objectives=list(dict.fromkeys(c['activity']['objective'] for c in checks))),metadata=dict(materials=['Cuaderno', 'Lápiz', 'Colores'],pedagogicalStatus='PENDIENTE_REVISION',note='Actividades de autoría didáctica a partir de la malla consultada; las producciones abiertas requieren revisión docente.'),steps=steps)
 if area=='matematicas' and grade==4:
  u['curriculum']['themes']=[t for t in u['curriculum']['themes'] if t!='Lo'];u['metadata']['pendingValidation']=['Fragmento final Lo en el eje temático: no se inventa un tema para completarlo']
 if extra:u['metadata'].update(extra)
 (BASE/(uid+'.json')).write_text(json.dumps(u,ensure_ascii=False,indent=2)+'\n')
 return u

def check(title,act,hint,visual=None,symbol=None,text=None):return dict(title=title,activity=act,hint=hint,visual=visual,symbol=symbol,text=text)

