make('matematicas',1,'numeros-cuerpos-datos','Números y formas de nuestra huerta','Imagina que contamos semillas y guardamos frutas en cajas. ¿Cómo podríamos organizar y contar todo?',[c1,c2,c3,c4,c5],[written('Escribe 264 como centenas, decenas y unidades. Escribe cómo se lee.','264 = 200 + 60 + 4: 2 centenas, 6 decenas y 4 unidades. Se lee doscientos sesenta y cuatro.'),written('Hay 135 semillas. Llegan 23 y después se usan 12. Escribe las dos operaciones y cuánto queda.','135 + 23 = 158. 158 − 12 = 146 semillas.'),written('Dibuja una lata, una pelota y una caja. Escribe cilindro, esfera o prisma debajo. Dibuja las barras de 5 mangos, 3 naranjas y 2 guayabas.','Lata: cilindro. Pelota: esfera. Caja rectangular: prisma. Las barras deben tener 5, 3 y 2 cuadros.')],dict(title='Organiza la cosecha',instruction='Dibuja una caja con 124 mangos y otra con 15. Escribe la suma y el total. Luego comprueba aquí el total.',activity=number('¿Cuántos mangos hay entre las dos cajas?',139,'124 + 15 = 139 mangos.','operaciones')),[check('centenas',number('¿Cuántas decenas hay en 478?',7,'El 7 está en las decenas: vale 70.','valor_posicional'),'Separa 400, 70 y 8.'),check('comparación',choice('¿Cuál es menor: 621 o 612?','612','Tienen seis centenas; una decena es menor que dos.','comparacion',['621','612','Son iguales']),'Compara las decenas.'),check('resta',number('De 158 plantas se trasladan 25. ¿Cuántas quedan?',133,'158 − 25 = 133.','operaciones'),'Quita dos decenas y cinco unidades.'),check('cuerpo',choice('¿Qué cuerpo tiene una base circular y una punta?','Cono','El cono tiene una base circular y termina en una punta.','cuerpos',['Cono','Cubo','Esfera']),'Mira los cuerpos del ejemplo.'),check('diagrama',number('¿Cuántas guayabas muestra el diagrama?',2,'Guayabas: dos cuadros.','datos'),'Lee la fila Guayabas.',bars)])

