 dict(phase='Arte',title='Una tarjeta para compartir',instruction='Haz una tarjeta con un dibujo y un gesto de cariño. Si tu familia celebra Navidad, puede ser navideña; si no, puede ser una tarjeta de agradecimiento. Usa papel o los dibujos digitales. Un adulto prepara cualquier recorte.',symbols=['✉️','🌻','⭐','🎄','❤️'],symbol='🎨'),
