 dict(phase='Hoy aprenderé',title='Conocemos nuestro lugar',instruction='Hoy vamos a jugar y conversar sobre Colombia y las personas de la comunidad. Un adulto puede acompañarte. Puedes responder señalando, hablando o con dibujos.',symbol='🏡'),
 dict(phase='Descubro',title='Nuestra bandera',instruction='Observa la bandera de Colombia. Señala amarillo, azul y rojo. Puedes decir sus nombres o mostrar el color que escuches.',visual={'kind':'flag'},symbol='🇨🇴'),
